// ignore_for_file: unused_element, unnecessary_cast

import '../feature_group_offline_store_config_data_catalog_config/feature_group_offline_store_config_data_catalog_config.dart';
import '../feature_group_offline_store_config_s3_storage_config/feature_group_offline_store_config_s3_storage_config.dart';

class FeatureGroupOfflineStoreConfig {
  /// The meta data of the Glue table that is autogenerated when an OfflineStore is created. See Data Catalog Config Below.
  final FeatureGroupOfflineStoreConfigDataCatalogConfig? dataCatalogConfig;

  /// Set to `true` to turn Online Store On.
  final bool? disableGlueTableCreation;

  /// The Amazon Simple Storage (Amazon S3) location of OfflineStore. See S3 Storage Config Below.
  final FeatureGroupOfflineStoreConfigS3StorageConfig s3StorageConfig;

  /// Format for the offline store table. Supported formats are `Glue` (Default) and Apache `Iceberg` (https://iceberg.apache.org/).
  final String? tableFormat;

  FeatureGroupOfflineStoreConfig({
    this.dataCatalogConfig,
    this.disableGlueTableCreation,
    required this.s3StorageConfig,
    this.tableFormat,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    final dataCatalogConfigValue = dataCatalogConfig;
    if (dataCatalogConfigValue != null) {
      map['dataCatalogConfig'] = dataCatalogConfigValue.toMap();
    }
    final disableGlueTableCreationValue = disableGlueTableCreation;
    if (disableGlueTableCreationValue != null) {
      map['disableGlueTableCreation'] = disableGlueTableCreationValue;
    }
    map['s3StorageConfig'] = s3StorageConfig.toMap();
    final tableFormatValue = tableFormat;
    if (tableFormatValue != null) {
      map['tableFormat'] = tableFormatValue;
    }
    return map;
  }

  factory FeatureGroupOfflineStoreConfig.fromMap(Map<String, dynamic> map) {
    return FeatureGroupOfflineStoreConfig(
      dataCatalogConfig: map['dataCatalogConfig'] == null
          ? null
          : FeatureGroupOfflineStoreConfigDataCatalogConfig.fromMap(
              (map['dataCatalogConfig'] as Map).cast<String, dynamic>()),
      disableGlueTableCreation: map['disableGlueTableCreation'] == null
          ? null
          : map['disableGlueTableCreation'] as bool,
      s3StorageConfig: FeatureGroupOfflineStoreConfigS3StorageConfig.fromMap(
          (map['s3StorageConfig'] as Map).cast<String, dynamic>()),
      tableFormat:
          map['tableFormat'] == null ? null : map['tableFormat'] as String,
    );
  }
}
